1	import type {ChatSession} from '../types/session.js';
2	import type {ToolRegistry, ToolContext} from './tools/registry.js';
3	import type {
4	  AIProvider,
5	  Message,
6	  MessageChunk,
7	  SendMessageParams,
8	  ToolCall,
9	  ToolResultContent,
10	  UsageMetadata,
11	} from '../types/ai.js';
12	import type {OutgoingMessage} from '../types/messages.js';
13	import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
14	import {toMessages, createContextConfig} from './conversationContext.js';
15	import type {ContextConfig} from './conversationContext.js';
16	import {
17	  shouldContinueToolLoop,
18	  collectText,
19	  buildToolCallMessages,
20	  collectToolCalls,
21	  extractStopReason,
22	  extractUsage,
23	} from './orchestratorHelpers.js';
24	import {appendEntry} from './entryMutations.js';
25	import {log} from '../shared/logger.js';
26	
27	const DEFAULT_MAX_TOOL_ROUNDS = 5;
28	
29	export interface OrchestratorHooks {
30	  beforeSession?: (session: ChatSession) => Promise<void>;
31	  afterSession?: (session: ChatSession) => Promise<void>;
32	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
33	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
34	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
35	  afterModelResponse?: (session: ChatSession, responseText: string, usage?: UsageMetadata) => Promise<void>;
36	  onError?: (session: ChatSession, error: Error) => Promise<void>;
37	}
38	
39	export interface ChatOrchestrator {
40	  processMessage(session: ChatSession): Promise<string>;
41	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
42	}
43	
44	export interface ChatOrchestratorOptions {
45	  maxToolRounds?: number;
46	  contextConfig?: Partial<ContextConfig>;
47	  promptBuilderOptions?: PromptBuilderOptions;
48	  hooks?: OrchestratorHooks;
49	}
50	
51	interface ToolExecutionResult {
52	  clientMessages: OutgoingMessage[];
53	  suppressOutput: boolean;
54	}
55	export function createChatOrchestrator(
56	  provider: AIProvider,
57	  promptBuilder: PromptBuilder,
58	  toolRegistry?: ToolRegistry,
59	  options?: ChatOrchestratorOptions
60	): ChatOrchestrator {
61	  const maxToolRounds = options?.maxToolRounds ?? DEFAULT_MAX_TOOL_ROUNDS;
62	  const contextConfig = createContextConfig(options?.contextConfig);
63	  const toolInstructions = toolRegistry?.getPromptInstructions();
64	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
65	  const tools = toolRegistry?.getDefinitions();
66	  const hooks = options?.hooks;
67	
68	  return {
69	    async processMessage(session: ChatSession): Promise<string> {
70	      return collectText(this.processMessageStream(session));
71	    },
72	
73	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
74	      if (hooks?.beforeSession) await hooks.beforeSession(session);
75	
76	      try {
77	        let userMessage = lastUserContent(session);
78	
79	        if (hooks?.beforeUserInput) {
80	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
81	        }
82	
83	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
84	
85	        const systemPrompt = hooks?.beforeModelResponse
86	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
87	          : baseSystemPrompt;
88	
89	        const messages: Message[] = toMessages(session.entries, contextConfig);
90	        let lastUsage: UsageMetadata | undefined;
91	        let responseText = '';
92	
93	        for (let round = 0; round <= maxToolRounds; round++) {
94	          log.info('orchestrator', 'starting round', {round});
95	          const pendingToolCalls: ToolCall[] = [];
96	
97	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
98	          responseText += outcome.text;
99	          lastUsage = outcome.usage ?? lastUsage;
100	
101	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
102	
103	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
104	          const {clientMessages, suppressOutput} = await executeToolCalls(
105	            pendingToolCalls,
106	            messages,
107	            toolRegistry!,
108	            session
109	          );
110	          log.info('orchestrator', 'tool execution complete', {
111	            clientMessageCount: clientMessages.length,
112	            clientMessageTypes: clientMessages.map(m => m.type),
113	            suppressOutput,
114	          });
115	
116	          if (clientMessages.length > 0) {
117	            yield {type: 'tool_result' as const, clientMessages};
118	          }
119	
120	          if (suppressOutput) {
121	            yield {type: 'suppress_output' as const};
122	          }
123	        }
124	
125	        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, lastUsage);
126	      } catch (error) {
127	        if (hooks?.onError && error instanceof Error) {
128	          await hooks.onError(session, error);
129	        }
130	        throw error;
131	      } finally {
132	        if (hooks?.afterSession) await hooks.afterSession(session);
133	      }
134	    },
135	  };
136	}
137	
138	interface RoundOutcome {
139	  stopReason: string;
140	  text: string;
141	  usage?: UsageMetadata;
142	}
143	
144	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
145	async function* streamRound(
146	  provider: AIProvider,
147	  request: SendMessageParams,
148	  pendingToolCalls: ToolCall[]
149	): AsyncGenerator<MessageChunk, RoundOutcome> {
150	  let stopReason = '';
151	  let text = '';
152	  let usage: UsageMetadata | undefined;
153	
154	  for await (const chunk of provider.sendMessage(request)) {
155	    yield chunk;
156	    collectToolCalls(chunk, pendingToolCalls);
157	    stopReason = extractStopReason(chunk) ?? stopReason;
158	    usage = extractUsage(chunk) ?? usage;
159	    if (chunk.type === 'text') text += chunk.text;
160	  }
161	
162	  return {stopReason, text, usage};
163	}
164	
165	// A changed message is also written back to the session's last user entry.
166	async function rewriteUserMessage(
167	  session: ChatSession,
168	  userMessage: string,
169	  hook: (session: ChatSession, userMessage: string) => Promise<string>
170	): Promise<string> {
171	  const modified = await hook(session, userMessage);
172	  if (modified === userMessage) return userMessage;
173	
174	  updateLastUserContent(session, modified);
175	  return modified;
176	}
177	
178	function lastUserContent(session: ChatSession): string {
179	  for (let i = session.entries.length - 1; i >= 0; i--) {
180	    const entry = session.entries[i];
181	    if (entry.role === 'user') return entry.content;
182	  }
183	  return '';
184	}
185	
186	function updateLastUserContent(session: ChatSession, content: string): void {
187	  for (let i = session.entries.length - 1; i >= 0; i--) {
188	    const entry = session.entries[i];
189	    if (entry.role === 'user') {
190	      entry.content = content;
191	      return;
192	    }
193	  }
194	}
195	
196	async function executeToolCalls(
197	  pendingToolCalls: ToolCall[],
198	  messages: Message[],
199	  toolRegistry: ToolRegistry,
200	  session: ChatSession
201	): Promise<ToolExecutionResult> {
202	  messages.push(buildToolCallMessages(pendingToolCalls));
203	
204	  const context: ToolContext = {
205	    userId: session.userId,
206	    sessionId: session.sessionId,
207	    workspaceId: session.workspaceId,
208	    authHeaders: session.authHeaders,
209	  };
210	
211	  const responses = await Promise.all(
212	    pendingToolCalls.map(async tc => {
213	      const response = await toolRegistry.execute(tc.name, tc.input, context);
214	      return {tc, response};
215	    })
216	  );
217	
218	  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
219	    type: 'tool_result' as const,
220	    toolUseId: tc.id,
221	    content: response.result,
222	  }));
223	  messages.push({role: 'user', content: toolResults});
224	
225	  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);
